// features/vendors.feature: "Vendors from another tenant are invisible"
import { PASSWORD, USERS, expect, expectStatus, test } from "../../fixtures";

// Assumes the seed includes a Globex Procurement user with the shared seed password.
const GLOBEX_USER = "member@globex.test";

test.describe("vendor tenant scoping", () => {
  test("vendors from another tenant are invisible", { tag: "@VEN-07" }, async ({ apiAs, request }) => {
    // Arrange: a vendor owned by the Globex Procurement tenant
    const globexLogin = await request.post("/api/auth/login", {
      data: { email: GLOBEX_USER, password: PASSWORD },
    });
    const { access_token: globexToken } = await expectStatus<{ access_token: string }>(globexLogin, 200);

    const uniqueName = `Globex Vendor ${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const created = await request.post("/api/vendors", {
      headers: { Authorization: `Bearer ${globexToken}` },
      data: { name: uniqueName, category: "services", contact_email: "ap@globex.test" },
    });
    const vendor = await expectStatus<{ id: string; name: string }>(created, 201);
    expect(vendor.name).toBe(uniqueName);

    // Act: the Northwind member requests that vendor by id
    const member = await apiAs("member");
    const response = await member.get(`/api/vendors/${vendor.id}`);

    // Assert
    const body = await expectStatus<{ error: { code: string } }>(response, 404);
    expect(body.error.code).toBe("vendor_not_found");
  });
});
